from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: "Expr"
    r: "Expr"


@dataclass
class Mul:
    l: "Expr"
    r: "Expr"


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an arithmetic expression tree.

    Num yields its value, Add yields the sum of its children,
    and Mul yields the product of its children.
    """
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)


def test_eval_num() -> None:
    assert eval_expr(Num(7)) == 7
    assert eval_expr(Num(-3)) == -3


def test_eval_add() -> None:
    assert eval_expr(Add(Num(1), Num(2))) == 3


def test_eval_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20


def test_eval_nested() -> None:
    # (1 + 2) * (3 + 4) = 21
    e = Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))
    assert eval_expr(e) == 21
